# Fuzzing has its own lockfile and graph. No fuzz dependency enters the 26-package
# native workspace or a normal node binary.
[workspace]
members = ["."]
resolver = "2"

[dependencies]
libfuzzer-sys = "=0.4.10"
trnm-protocol = { version = "=0.1.0", path = "../../trillionnium/crates/trnm-protocol" }
trnm-crypto-primitives = { version = "=0.1.0", path = "../../trillionnium/crates/trnm-crypto-primitives" }
trnm-pon-node = { version = "=0.1.0", path = "../../trillionnium/crates/trnm-pon-node" }
trnm-mvcc-fee = { version = "=0.1.0", path = "../../trillionnium/crates/trnm-mvcc-fee" }
serde_json = "=1.0.149"
